#include <bits/stdc++.h>
using namespace std;

struct Orientation {
    vector<pair<int,int>> cells;
    int w, h;
    int r, f;
};

vector<Orientation> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Orientation> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> transformed;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx;
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx;
                    tx = nx; ty = ny;
                }
                transformed.push_back({tx, ty});
            }
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x, y] : transformed) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x, y] : transformed) { x -= minx; y -= miny; }
            sort(transformed.begin(), transformed.end());
            if (seen.insert(transformed).second) {
                int maxx = 0, maxy = 0;
                for (auto [x, y] : transformed) { maxx = max(maxx, x); maxy = max(maxy, y); }
                res.push_back({transformed, maxx + 1, maxy + 1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> rawCells(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        cin >> ksz[i];
        rawCells[i].resize(ksz[i]);
        for (int j = 0; j < ksz[i]; j++) {
            cin >> rawCells[i][j].first >> rawCells[i][j].second;
        }
        totalCells += ksz[i];
    }

    vector<vector<Orientation>> allOrients(n);
    for (int i = 0; i < n; i++) {
        allOrients[i] = getOrientations(rawCells[i]);
    }

    // Sort pieces by decreasing size, then fewer orientations
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if (ksz[a] != ksz[b]) return ksz[a] > ksz[b];
        return allOrients[a].size() < allOrients[b].size();
    });

    int bestArea = INT_MAX;
    int bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    int sqrtArea = (int)ceil(sqrt((double)totalCells));

    // Find max piece width across all orientations
    int maxPieceW = 0;
    for (int i = 0; i < n; i++)
        for (auto& o : allOrients[i])
            maxPieceW = max(maxPieceW, min(o.w, o.h));

    auto startTime = chrono::steady_clock::now();

    auto elapsed_ms = [&]() -> long long {
        return chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - startTime).count();
    };

    // Collect candidate widths
    vector<int> candidateW;
    for (int w = max(maxPieceW, sqrtArea - 5); w <= sqrtArea + 100 && w <= totalCells; w++) {
        candidateW.push_back(w);
    }
    // Add wider options
    for (int w = sqrtArea + 101; w <= min(totalCells, sqrtArea * 3); w += 5) {
        candidateW.push_back(w);
    }
    // Sort by expected area (W * ceil(totalCells/W))
    sort(candidateW.begin(), candidateW.end(), [&](int a, int b){
        long long areaA = (long long)a * ((totalCells + a - 1) / a);
        long long areaB = (long long)b * ((totalCells + b - 1) / b);
        return areaA < areaB;
    });

    for (int W : candidateW) {
        if (elapsed_ms() > 8500) break;
        if ((long long)W * ((totalCells + W - 1) / W) >= bestArea) continue;

        // Use column heights for skyline
        vector<int> colHeight(W, 0);

        // Use a hash set for occupied cells
        unordered_set<long long> occupied;
        occupied.reserve(totalCells * 2);

        auto key = [&](int x, int y) -> long long {
            return (long long)x * 1000000LL + y;
        };

        vector<int> px(n), py(n), pr(n), pf(n);
        bool valid = true;
        int currentMaxH = 0;

        for (int idx = 0; idx < n; idx++) {
            if (elapsed_ms() > 9000) { valid = false; break; }
            int i = order[idx];

            int bestScore = INT_MAX;
            int bx = -1, by = -1;
            int bori = -1;

            for (int oi = 0; oi < (int)allOrients[i].size(); oi++) {
                auto& ori = allOrients[i][oi];
                if (ori.w > W) continue;

                for (int x = 0; x <= W - ori.w; x++) {
                    // Estimate min y from column heights
                    int minY = 0;
                    for (auto [cx, cy] : ori.cells) {
                        minY = max(minY, colHeight[x + cx] - cy);
                    }
                    if (minY < 0) minY = 0;

                    for (int y = minY; ; y++) {
                        int newH = max(currentMaxH, y + ori.h);
                        int score = newH * 1000000 + y * 1000 + x;
                        if (score >= bestScore) break;

                        bool ok = true;
                        for (auto [cx, cy] : ori.cells) {
                            if (occupied.count(key(x+cx, y+cy))) { ok = false; break; }
                        }
                        if (ok) {
                            bestScore = score;
                            bx = x; by = y; bori = oi;
                            break;
                        }
                        if (y > minY + 20) break;
                    }
                }
            }

            if (bx < 0) { valid = false; break; }

            auto& ori = allOrients[i][bori];
            px[i] = bx; py[i] = by; pr[i] = ori.r; pf[i] = ori.f;
            for (auto [cx, cy] : ori.cells) {
                occupied.insert(key(bx+cx, by+cy));
                colHeight[bx+cx] = max(colHeight[bx+cx], by+cy+1);
                currentMaxH = max(currentMaxH, by+cy+1);
            }
        }

        if (!valid) continue;

        int H = currentMaxH;
        long long area = (long long)W * H;
        if (area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))) {
            bestArea = area;
            bestW = W; bestH = H;
            bestX = px; bestY = py; bestR = pr; bestF = pf;
        }
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
    }
    return 0;
}
